import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as s,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"合併和排序 Linux 上的文件 | LCTT x X-CMD","titleTemplate":false,"description":"合併和排序 Linux 上的文件 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"合併和排序 Linux 上的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"合併和排序 Linux 上的文件 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200810 Merging and sorting files on Linux","title":"合併和排序 Linux 上的文件","tag":"202008","desc":""},"relativePath":"202008/20200810 Merging and sorting files on Linux.md","filePath":"[post].md"}'),h={name:"202008/20200810 Merging and sorting files on Linux.md"};function c(g,e,k,f,u,b){const a=p("Link");return o(),d("div",null,[e[15]||(e[15]=r(`<h1 id="合併和排序-linux-上的文件" tabindex="-1">合併和排序 Linux 上的文件 <a class="header-anchor" href="#合併和排序-linux-上的文件" aria-label="Permalink to “合併和排序 Linux 上的文件”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202008/22/102250i3943is48r34w4nz.jpg" alt=""></p><p>在 Linux 上合併和排序文本的方法有很多種，但如何去處理它取決於你試圖做什麼：你是隻想將多個文件的內容放入一個文件中，還是以某種方式組織它，讓它更易於使用。在本文中，我們將查看一些用於排序和合並文件內容的命令，並重點介紹結果有何不同。</p><h3 id="使用-cat" tabindex="-1">使用 cat <a class="header-anchor" href="#使用-cat" aria-label="Permalink to “使用 cat”">​</a></h3><p>如果你只想將一組文件放到單個文件中，那麼 <code>cat</code> 命令是一個容易的選擇。你所要做的就是輸入 <code>cat</code>，然後按你希望它們在合併文件中的順序在命令列中列出這些文件。將命令的輸出重定向到要創建的文件。如果指定名稱的文件已經存在，那麼文件將被覆蓋。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat firstfile secondfile thirdfile &gt; newfile</span></span></code></pre></div><p>如果要將一系列文件的內容添加到現有文件中，而不是覆蓋它，只需將 <code>&gt;</code> 變成 <code>&gt;&gt;</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat firstfile secondfile thirdfile &gt;&gt; updated_file</span></span></code></pre></div><p>如果你要合併的文件遵循一些方便的命名約定，那麼任務可能更簡單。如果可以使用正則表達式指定所有文件名，那就不必列出所有文件。例如，如果文件全部以 <code>file</code> 結束，如上所示，你可以進行如下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat *file &gt; allfiles</span></span></code></pre></div><p>請注意，上面的命令將按字母數字順序添加文件內容。在 Linux 上，一個名為 <code>filea</code> 的文件將排在名為 <code>fileA</code> 的文件的前面，但會在 <code>file7</code> 的後面。畢竟，當我們處理字母數字序列時，我們不僅需要考慮 <code>ABCDE</code>，還需要考慮 <code>0123456789aAbBcCdDeE</code>。你可以使用 <code>ls *file</code> 這樣的命令來查看合併文件之前文件的順序。</p><p>注意：首先確保你的命令包含合併文件中所需的所有文件，而不是其他文件，尤其是你使用 <code>*</code> 等通配符時。不要忘記，用於合併的文件仍將單獨存在，在確認合併後，你可能想要刪除這些文件。</p><h3 id="按時間期限合併文件" tabindex="-1">按時間期限合併文件 <a class="header-anchor" href="#按時間期限合併文件" aria-label="Permalink to “按時間期限合併文件”">​</a></h3><p>如果要基於每個文件的時間期限而不是文件名來合併文件，請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for file in \`ls -tr myfile.*\`; do  cat $file &gt;&gt; BigFile.$$; done</span></span></code></pre></div><p>使用 <code>-tr</code> 選項（<code>t</code> = 時間，<code>r</code> = 反向）將產生按照最早的在最前排列的文件列表。例如，如果你要保留某些活動的日誌，並且希望按活動執行的順序添加內容，則這非常有用。</p><p>上面命令中的 <code>$$</code> 表示運行命令時的進程 ID。不是很必要使用此功能，但它幾乎不可能會無意添加到現有的文件，而不是創建新文件。如果使用 <code>$$</code>，那麼生成的文件可能如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l BigFile.*</span></span>
<span class="line"><span>-rw-rw-r-- 1 justme justme   931725 Aug  6 12:36 BigFile.582914</span></span></code></pre></div><h3 id="合併和排序文件" tabindex="-1">合併和排序文件 <a class="header-anchor" href="#合併和排序文件" aria-label="Permalink to “合併和排序文件”">​</a></h3><p>Linux 提供了一些有趣的方式來對合並之前或之後的文件內容進行排序。</p><h4 id="按字母對內容進行排序" tabindex="-1">按字母對內容進行排序 <a class="header-anchor" href="#按字母對內容進行排序" aria-label="Permalink to “按字母對內容進行排序”">​</a></h4><p>如果要對合並的文件內容進行排序，那麼可以使用以下命令對整體內容進行排序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat myfile.1 myfile.2 myfile.3 | sort &gt; newfile</span></span></code></pre></div><p>如果要按文件對內容進行分組，請使用以下命令對每個文件進行排序，然後再將它添加到新文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for file in \`ls myfile.?\`; do sort $file &gt;&gt; newfile; done</span></span></code></pre></div><h4 id="對文件進行數字排序" tabindex="-1">對文件進行數字排序 <a class="header-anchor" href="#對文件進行數字排序" aria-label="Permalink to “對文件進行數字排序”">​</a></h4><p>要對文件內容進行數字排序，請在 <code>sort</code> 中使用 <code>-n</code> 選項。僅當文件中的行以數字開頭時，此選項才有用。請記住，按照默認順序，<code>02</code> 將小於 <code>1</code>。當你要確保行以數字排序時，請使用 <code>-n</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat myfile.1 myfile.2 myfile.3 | sort -n &gt; xyz</span></span></code></pre></div><p>如果文件中的行以 <code>2020-11-03</code> 或 <code>2020/11/03</code>（年月日格式）這樣的日期格式開頭，<code>-n</code> 選項還能讓你按日期對內容進行排序。其他格式的日期排序將非常棘手，並且將需要更復雜的命令。</p><h3 id="使用-paste" tabindex="-1">使用 paste <a class="header-anchor" href="#使用-paste" aria-label="Permalink to “使用 paste”">​</a></h3><p><code>paste</code> 命令允許你逐行連接文件內容。使用此命令時，合併文件的第一行將包含要合併的每個文件的第一行。以下是示例，其中我使用了大寫字母以便於查看行的來源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file.a</span></span>
<span class="line"><span>A one</span></span>
<span class="line"><span>A two</span></span>
<span class="line"><span>A three</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ paste file.a file.b file.c</span></span>
<span class="line"><span>A one   B one   C one</span></span>
<span class="line"><span>A two   B two   C two</span></span>
<span class="line"><span>A three B three C thee</span></span>
<span class="line"><span>        B four  C four</span></span>
<span class="line"><span>                C five</span></span></code></pre></div><p>將輸出重定向到另一個文件來保存它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ paste file.a file.b file.c &gt; merged_content</span></span></code></pre></div><p>或者，你可以將每個文件的內容在同一行中合併，然後將文件粘貼在一起。這需要使用 <code>-s</code>（序列）選項。注意這次的輸出如何顯示每個文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ paste -s file.a file.b file.c</span></span>
<span class="line"><span>A one   A two   A three</span></span>
<span class="line"><span>B one   B two   B three B four</span></span>
<span class="line"><span>C one   C two   C thee  C four  C five</span></span></code></pre></div><h3 id="使用-join" tabindex="-1">使用 join <a class="header-anchor" href="#使用-join" aria-label="Permalink to “使用 join”">​</a></h3><p>合併文件的另一個命令是 <code>join</code>。<code>join</code> 命令讓你能基於一個共同字段合併多個文件的內容。例如，你可能有一個包含一組同事的電話的文件，其中，而另一個包含了同事的電子郵件地址，並且兩者均按個人姓名列出。你可以使用 <code>join</code> 創建一個包含電話和電子郵件地址的文件。</p><p>一個重要的限制是文件的行必須是相同的順序，並在每個文件中包括用於連接的字段。</p><p>這是一個示例命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ join phone_numbers email_addresses</span></span>
<span class="line"><span>Sandra 555-456-1234 bugfarm@gmail.com</span></span>
<span class="line"><span>Pedro 555-540-5405</span></span>
<span class="line"><span>John 555-333-1234 john_doe@gmail.com</span></span>
<span class="line"><span>Nemo 555-123-4567 cutie@fish.com</span></span></code></pre></div><p>在本例中，即使缺少附加信息，第一個字段（名字）也必須存在於每個文件中，否則命令會因錯誤而失敗。對內容進行排序有幫助，而且可能更容易管理，但只要順序一致，就不需要這麼做。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在 Linux 上，你有很多可以合併和排序存儲在單獨文件中的數據的方式。這些方法可以使原本繁瑣的任務變得異常簡單。</p><hr>`,45)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://www.networkworld.com/article/3570508/merging-and-sorting-files-on-linux.html"},{default:n(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3570508/merging-and-sorting-files-on-linux.html",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),i(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const y=l(h,[["render",c]]);export{C as __pageData,y as default};
